{
  "Teaching Material": {
    "knowledge_point": "The Doctrine of Precedent in Common Law Systems",
    "title": "Precedent: Follow, Distinguish, or Overrule?",
    "lesson_overview": {
      "course_level": "Introductory or intermediate law",
      "duration_minutes": 90,
      "central_question": "When, why, and to what extent must a court follow an earlier judicial decision?",
      "teaching_mode": "Interactive lecture, case analysis, comparative discussion, and collaborative case conference",
      "scope_note": "This lesson presents the general structure of precedent in common law systems. The exact force of precedent varies by jurisdiction, court hierarchy, subject matter, and constitutional arrangement. Students should verify the current rule in the relevant legal system and should not assume that English, United States, Australian, Canadian, Indian, and other common law approaches are identical."
    },
    "essential_questions": [
      "What is the difference between precedent and stare decisis?",
      "What part of a judicial decision is binding?",
      "How do court hierarchy and jurisdiction affect the authority of a decision?",
      "When should a court follow, distinguish, reverse, or overrule a precedent?",
      "What values support precedent, and what risks arise from following it?",
      "How does precedent interact with legislation, constitutional law, and foreign authority?"
    ],
    "teaching_objectives": [
      {
        "id": "LO1",
        "objective": "Define precedent, stare decisis, binding authority, persuasive authority, ratio decidendi, and obiter dicta.",
        "bloom_level": "Understand"
      },
      {
        "id": "LO2",
        "objective": "Identify the material facts, legal issue, holding, ratio, and relevant statements in obiter from a judicial decision.",
        "bloom_level": "Analyze"
      },
      {
        "id": "LO3",
        "objective": "Determine whether a judicial decision is binding, persuasive, distinguishable, or no longer authoritative in a particular case.",
        "bloom_level": "Apply"
      },
      {
        "id": "LO4",
        "objective": "Explain the operation of vertical and horizontal precedent within a court hierarchy.",
        "bloom_level": "Understand"
      },
      {
        "id": "LO5",
        "objective": "Distinguish between following a precedent, distinguishing a case, reversing a decision, and overruling a precedent.",
        "bloom_level": "Analyze"
      },
      {
        "id": "LO6",
        "objective": "Evaluate the benefits and limitations of stare decisis, including consistency, predictability, equality, judicial error, rigidity, and democratic legitimacy.",
        "bloom_level": "Evaluate"
      },
      {
        "id": "LO7",
        "objective": "Communicate a reasoned case analysis using an issue-rule-authority-application-conclusion structure.",
        "bloom_level": "Create"
      }
    ],
    "key_points": [
      {
        "id": "KP1",
        "heading": "Precedent and stare decisis",
        "explanation": "Precedent is a prior judicial decision or legal principle used as authority in a later dispute. Stare decisis is the doctrine or policy of adhering to relevant earlier holdings. Precedent promotes consistency, predictability, equality, efficient administration of justice, and legitimate expectations.",
        "classroom_takeaway": "Following precedent is a legal method for maintaining stability; it does not mean that the earlier court was necessarily correct."
      },
      {
        "id": "KP2",
        "heading": "The anatomy of a judicial decision",
        "explanation": "A judgment normally contains facts, procedural history, legal issues, reasons, and a disposition. The ratio decidendi is the legal principle necessary to the result. Obiter dicta are observations that may be relevant or persuasive but were not necessary to decide the case.",
        "classroom_takeaway": "Not every statement in a judgment creates binding precedent."
      },
      {
        "id": "KP3",
        "heading": "Bindingness depends on several factors",
        "explanation": "The authority of a decision depends on the court hierarchy, jurisdiction, subject matter, legal issue, procedural posture, and whether the court is applying constitutional, statutory, or common law.",
        "classroom_takeaway": "A case may be highly persuasive in one court or jurisdiction but binding in another."
      },
      {
        "id": "KP4",
        "heading": "Vertical and horizontal precedent",
        "explanation": "Vertical precedent generally means that a higher court binds lower courts within the relevant hierarchy. Horizontal precedent concerns the treatment of decisions by courts at the same or a coordinate level. The strength of horizontal precedent varies considerably between systems.",
        "classroom_takeaway": "A lower court usually cannot simply reject a controlling decision of a higher court."
      },
      {
        "id": "KP5",
        "heading": "Follow, distinguish, reverse, and overrule",
        "explanation": "A court follows a precedent when the legal issue and material facts are sufficiently similar. It distinguishes a case when a legally material factual or legal difference prevents the precedent from applying. An appellate court reverses the decision in the particular case, whereas an authorized court overrules a precedent by changing or abandoning the earlier legal rule.",
        "classroom_takeaway": "Distinguishing is not a disguised method of ignoring precedent; the difference must be genuine and material."
      },
      {
        "id": "KP6",
        "heading": "Precedent is not mechanical",
        "explanation": "Courts use analogical reasoning. They identify legally relevant similarities and differences, address adverse arguments, and explain why the authority should or should not control. Courts may also limit the scope of a precedent when the earlier judgment is ambiguous or the legal issue is different.",
        "classroom_takeaway": "The legal issue and material facts matter more than shared subject matter or similar wording."
      },
      {
        "id": "KP7",
        "heading": "Relationship with legislation and constitutional law",
        "explanation": "Precedent operates alongside statutes, constitutions, treaties, regulations, and other legal sources. A legislature may expressly or impliedly change a common law rule, subject to constitutional and interpretive rules. Constitutional precedent may receive different treatment from statutory precedent, depending on the jurisdiction.",
        "classroom_takeaway": "Always check whether a later statute or constitutional provision affects an earlier judicial decision."
      },
      {
        "id": "KP8",
        "heading": "Benefits and costs of precedent",
        "explanation": "Benefits include consistency, predictability, equality, protection of reasonable reliance, and reduced judicial inconsistency. Costs include rigidity, persistence of erroneous decisions, difficulty correcting mistakes, increased litigation costs, delay, and concerns about judges making law with limited democratic accountability.",
        "classroom_takeaway": "The doctrine balances institutional stability against the need for legal correctness and adaptability."
      },
      {
        "id": "KP9",
        "heading": "Multiple opinions and subsequent treatment",
        "explanation": "In decisions with a majority, plurality, concurring, and dissenting opinions, the majority's necessary reasoning generally carries the greatest precedential weight. Concurring opinions and dissents may be persuasive. Later appellate decisions, legislative changes, and authoritative commentary may also modify the practical value of a precedent.",
        "classroom_takeaway": "Read the entire judgment and check its subsequent history rather than relying on a single quotation."
      },
      {
        "id": "KP10",
        "heading": "A practical four-question test",
        "explanation": "Before following a case, ask: Which court decided it? Is the decision from the relevant jurisdiction? Is the legal issue the same? What part of the decision was necessary to the result, and is there a genuine material difference in the facts?",
        "classroom_takeaway": "Court, jurisdiction, issue, ratio, and material facts provide a practical checklist for precedent analysis."
      }
    ],
    "core_terms": [
      {
        "term": "Precedent",
        "definition": "A prior judicial decision or legal principle used as authority in a later case."
      },
      {
        "term": "Stare decisis",
        "definition": "The doctrine or policy of adhering to relevant earlier judicial decisions; literally, to stand by things decided."
      },
      {
        "term": "Ratio decidendi",
        "definition": "The legal principle necessary to the decision and therefore capable of binding later cases within the relevant hierarchy."
      },
      {
        "term": "Obiter dicta",
        "definition": "Statements in a judgment that are not necessary to the result. They may be persuasive but are generally not binding."
      },
      {
        "term": "Binding authority",
        "definition": "A decision or legal source that the relevant court must follow when deciding the same legal issue."
      },
      {
        "term": "Persuasive authority",
        "definition": "A decision, source, or legal argument that may influence the court but does not formally control its decision."
      },
      {
        "term": "Vertical precedent",
        "definition": "The authority of a higher court for lower courts within the same jurisdictional hierarchy."
      },
      {
        "term": "Horizontal precedent",
        "definition": "The authority of decisions made by courts at the same or a coordinate level; its force varies by jurisdiction."
      },
      {
        "term": "Distinguish",
        "definition": "To decide a case without directly applying a precedent because a material legal or factual difference makes the precedent inapplicable."
