        "term": "Basic open",
        "definition": "D(f) is the basic open on which the function f is invertible."
      },
      {
        "term": "Generic point",
        "definition": "The point q of V(q), whose closure is V(q)."
      },
      {
        "term": "Local ring",
        "definition": "O_{X,p} is the stalk of the structure sheaf at p; for X = Spec A, it is A_p."
