  "common_misconceptions_and_responses": [
    {
      "misconception": "Every chain is a cycle.",
      "correction": "A chain is a cycle only when its boundary is zero."
    },
    {
      "misconception": "H₀(X;Z) is always Z.",
      "correction": "For a nonempty path-connected space it is Z; otherwise it is a free group with one generator for each path component."
    },
    {
      "misconception": "Cohomology is always the direct dual of homology.",
      "correction": "The Ext term must be included, and it shifts torsion by one degree."
    },
    {
      "misconception": "Tensor product computes all homology with new coefficients.",
      "correction": "The simple tensor formula is not valid in the presence of torsion without additional information."
    },
    {
      "misconception": "A short exact sequence determines its middle object canonically.",
      "correction": "It often splits, but the splitting may be noncanonical."
    },
    {
      "misconception": "Cup product is always ordinary commutative.",
      "correction": "It is graded commutative, and degree-one products can be nonzero."
    },
    {
      "misconception": "The number and dimensions of cells directly give homology ranks.",
      "correction": "Cells determine the chain groups, but boundary maps and their incidence numbers determine homology."
    }
  ],
