{
  "Teaching Material": {
    "basic_information": {
      "title": "Advanced Algorithms: Graph Theory and Network Flow",
      "course_level": "Advanced undergraduate or graduate algorithms course",
      "unit_duration": "3 sessions × 90 minutes",
      "topic_scope": "Graph modeling, graph traversal, structural graph algorithms, shortest paths, minimum spanning trees, maximum flow, minimum cut, Dinic's algorithm, and flow-based reductions such as bipartite matching.",
      "central_question": "How can a real problem be modeled as a graph, and how can the appropriate graph algorithm be selected, justified, implemented, and analyzed?"
    },
    "prerequisites": [
      "Data structures including queues, stacks, priority queues, and disjoint sets",
      "Basic graph terminology such as vertices, edges, paths, cycles, and connectivity",
      "Asymptotic analysis and Big-O complexity",
      "Recursion and iterative traversal",
      "Basic proof techniques, including invariants and contradiction",
      "Programming proficiency in Python, Java, C++, or an equivalent language"
    ],
    "teaching_objectives": {
      "knowledge_understanding": [
        "Represent a problem as a directed or undirected, weighted or unweighted graph.",
        "Explain the purpose and assumptions of BFS, DFS, topological sorting, strongly connected components, minimum spanning trees, and shortest-path algorithms.",
        "Define a flow network, feasible flow, flow value, residual graph, augmenting path, maximum flow, and minimum cut.",
        "State and explain the Max-Flow Min-Cut theorem.",
        "Describe how maximum flow models bipartite matching and related allocation problems."
      ],
      "algorithmic_skills": [
        "Choose an appropriate graph algorithm based on graph structure, edge properties, and optimization objective.",
        "Trace BFS, Dijkstra's algorithm, Kruskal's algorithm, and Dinic's algorithm step by step.",
        "Implement residual graphs, augmenting paths, level graphs, and blocking flows.",
        "Analyze time and space complexity under both sparse and dense graph assumptions.",
        "Test algorithms on normal, boundary, and adversarial inputs."
      ],
      "problem_solving_and_proof": [
        "Construct a valid graph abstraction and justify the meaning of vertices, edges, weights, directions, and capacities.",
        "Prove correctness using loop invariants, the cut property, the shortest-path property, or the Max-Flow Min-Cut theorem.",
        "Diagnose incorrect implementations and distinguish algorithmic errors from modeling errors.",
        "Evaluate whether a polynomial-time result is efficient for the expected graph size."
      ],
      "practical_and_collaborative": [
        "Work in teams by separating graph modeler, tracer, implementer, and verifier roles.",
        "Explain an algorithm and its complexity clearly in written or oral form.",
        "Compare multiple algorithms in terms of correctness, complexity, implementation difficulty, and practical performance."
      ]
    },
    "success_criteria": [
      "A student can select and justify an algorithm for at least 80% of standard graph problem scenarios.",
      "A student can construct a flow network that correctly represents a practical resource-allocation or matching problem.",
      "A student can implement Dinic's algorithm with correct residual-edge updates and reasonable complexity analysis.",
      "A student can prove that a computed flow is maximum by identifying a corresponding minimum cut.",
      "A student can distinguish shortest-path, minimum-spanning-tree, matching, and maximum-flow objectives."
    ],
    "key_points": [
      {
        "topic": "Graph modeling and representation",
        "core_ideas": [
          "A graph is an abstraction whose vertices represent entities and whose edges represent interactions.",
          "Edge direction, weight, multiplicity, and capacity must reflect the semantics of the problem.",
          "Adjacency lists are appropriate for sparse graphs and generally require O(V + E) space.",
          "Adjacency matrices are appropriate when the graph is dense or constant-time edge lookup is important."
        ],
        "important_algorithms": [
          "BFS and DFS: O(V + E)",
          "Topological sorting with Kahn's algorithm or DFS: O(V + E)",
          "Tarjan or Kosaraju for strongly connected components: O(V + E)"
        ]
      },
      {
        "topic": "Minimum spanning trees",
        "core_ideas": [
          "A minimum spanning tree connects every vertex with minimum total edge weight and contains no cycle.",
          "The problem is distinct from the shortest-path problem.",
          "The cut property supports greedy correctness."
        ],
        "important_algorithms": [
          "Kruskal's algorithm: O(E log E) with union-find",
          "Prim's algorithm: O(E log V) with an adjacency list and priority queue"
        ]
      },
      {
        "topic": "Shortest paths",
        "core_ideas": [
          "BFS solves unweighted shortest paths in O(V + E).",
          "Dijkstra's algorithm solves single-source shortest paths with nonnegative edge weights in O((V + E) log V).",
          "Bellman-Ford handles negative edges in O(VE) and can detect a negative cycle.",
          "Shortest paths in a directed acyclic graph can be processed in topological order in O(V + E)."
        ],
        "correctness_idea": "When Dijkstra removes a vertex with minimum tentative distance from the priority queue, no path through an unprocessed vertex can produce a shorter distance to it."
      },
      {
        "topic": "Flow networks and residual graphs",
        "core_ideas": [
          "A flow network has a source s, a sink t, directed edges, nonnegative capacities, and optional lower bounds.",
          "A feasible flow obeys capacity constraints and flow conservation at intermediate vertices.",
          "A residual edge represents unused capacity in the forward direction and cancellation capacity in the reverse direction.",
          "An augmenting path increases the flow by its bottleneck capacity.",
          "The absence of an augmenting path is equivalent to maximum flow."
        ]
      },
      {
        "topic": "Maximum flow and minimum cut",
        "core_ideas": [
          "The value of a maximum flow equals the capacity of a minimum s-t cut.",
          "Only edges directed from the source side of a cut to the sink side contribute to cut capacity.",
          "A minimum cut explains which constraints prevent additional flow."
        ],
        "correctness_idea": "Every flow crosses every s-t cut no more times than the cut capacity. When no augmenting path remains, the vertices reachable from s define a cut whose capacity equals the current flow value."
      },
      {
        "topic": "Dinic's algorithm",
        "core_ideas": [
          "BFS constructs a level graph using residual edges.",
          "DFS sends a blocking flow along edges that advance exactly one level.",
          "Current-edge pointers prevent repeatedly scanning unusable edges.",
          "The algorithm repeats BFS and blocking-flow phases until the sink is unreachable in the residual graph."
        ],
        "complexity": "O(V²E) for general capacitated networks; often substantially faster in practice and on unit-capacity or bipartite networks."
      },
      {
        "topic": "Flow-based reductions",
        "core_ideas": [
