    "core_teaching_content": {
      "module_1_graph_abstraction": {
        "topics": [
          "Directed versus undirected graphs",
          "Weighted versus unweighted graphs",
          "Simple graphs, multigraphs, bipartite graphs, and directed acyclic graphs",
          "Connectivity, cycles, topological order, and strongly connected components"
        ],
        "modeling_process": [
          "Identify the entities that become vertices.",
          "Identify the allowed interactions that become edges.",
          "Decide whether each interaction is directional.",
          "Assign weights, capacities, or unit limits only when they represent actual problem constraints.",
          "State the objective before selecting an algorithm.",
          "Test the model on a tiny instance with a known answer."
        ]
      },
      "module_2_structural_and_tree_algorithms": {
        "topics": [
          "BFS and DFS",
          "Topological sorting",
          "Strongly connected components",
          "Minimum spanning trees and union-find"
        ],
        "key_contrasts": [
          "A path minimizes the sum or number of edges between specified vertices; a spanning tree minimizes the total cost of connecting an entire graph.",
          "Topological sorting exists only for directed acyclic graphs.",
          "A shortest-path tree preserves shortest-path distances; a minimum spanning tree does not necessarily do so."
        ]
      },
      "module_3_shortest_paths": {
        "topics": [
          "Unweighted shortest paths",
          "Dijkstra's algorithm",
          "Bellman-Ford and negative cycles",
          "DAG shortest paths"
        ],
        "implementation_requirements": [
          "Maintain a distance estimate and predecessor for each vertex.",
          "Ignore stale priority-queue entries.",
          "Check assumptions before applying Dijkstra.",
          "Detect unreachable vertices explicitly."
        ]
      },
      "module_4_flow_theory": {
        "definitions": [
          "A flow network contains a source s, a sink t, directed edges, and edge capacities.",
          "A feasible flow satisfies 0 ≤ f(u,v) ≤ c(u,v) and flow conservation at all intermediate vertices.",
          "The flow value is the total flow leaving s, equivalently the total flow entering t.",
          "A cut partitions the vertices into source side S and sink side T.",
          "The cut capacity is the sum of capacities of original edges directed from S to T."
        ],
        "residual_graph_definition": [
          "For each original edge u → v, the forward residual capacity is c(u,v) - f(u,v).",
          "The reverse residual capacity is f(u,v).",
          "An augmenting path is a residual s-t path whose bottleneck is the minimum residual capacity along the path."
        ],
        "max_flow_min_cut_proof_outline": [
          "Any feasible flow is bounded above by the capacity of every s-t cut.",
          "If no augmenting path exists, let S be the vertices reachable from s in the residual graph.",
          "All edges from S to the complement are saturated, establishing a cut with capacity equal to the current flow.",
          "The current flow is therefore both feasible and equal to a cut upper bound, so it is maximum."
        ]
      },
      "module_5_maximum_flow_algorithms": {
        "algorithm_comparison": [
          {
            "algorithm": "Ford-Fulkerson",
            "main_idea": "Repeatedly augment along any residual s-t path.",
            "complexity": "O(E times maximum-flow value) for integer capacities",
            "warning": "Path choices can cause poor running time."
          },
          {
            "algorithm": "Edmonds-Karp",
            "main_idea": "Repeatedly choose a residual s-t path with the fewest edges.",
            "complexity": "O(VE²)"
          },
          {
            "algorithm": "Dinic",
            "main_idea": "Construct a level graph and send a blocking flow in each phase.",
            "complexity": "O(V²E) in general"
          },
          {
            "algorithm": "Push-relabel",
            "main_idea": "Maintain a preflow and push excess flow toward the sink, followed by relabeling.",
            "complexity": "O(V³) with a standard general implementation",
            "role": "Important alternative for dense networks; optional extension."
          }
        ],
        "dinic_pseudocode": [
          "Construct the residual graph.",
          "Repeat:",
          "  Run BFS on residual edges to assign levels; stop if t is unreachable.",
          "  Set the current-edge pointer of every vertex to its first outgoing residual edge.",
          "  Repeatedly run level-respecting DFS from s to send a blocking flow to t.",
          "  Stop the blocking-flow phase when t is unreachable in the level graph.",
          "Return the flow and the reachable source-side set of the final minimum cut."
        ]
      },
      "module_6_reductions": {
        "bipartite_matching_construction": [
          "Create one vertex for every left-side element and every right-side element.",
          "Create a source s.",
          "Create a sink t.",
          "Add an edge s → u with capacity 1 for every left vertex u.",
          "Add an edge u → v with capacity 1 for every allowed left-right pair.",
          "Add an edge v → t with capacity 1 for every right vertex v.",
          "An integral maximum flow corresponds to a maximum-cardinality matching."
        ],
        "optional_extensions": [
          "Minimum-cost flow using shortest residual augmenting paths",
          "Circulation with lower and upper bounds",
          "Vertex-capacitated flow through vertex splitting",
          "Push-relabel and highest-label refinements"
        ]
      }
    },
    "algorithm_selection_guide": [
      {
        "problem": "Reachability or shortest path in an unweighted graph",
        "recommended_method": "BFS",
        "reason": "BFS explores vertices in nondecreasing path length."
      },
      {
        "problem": "Single-source shortest paths with nonnegative weights",
        "recommended_method": "Dijkstra",
        "reason": "Greedy selection is valid because settled distances cannot later decrease."
      },
      {
        "problem": "Negative edges or possible negative cycles",
        "recommended_method": "Bellman-Ford",
        "reason": "It supports negative edges and can detect negative cycles."
      },
      {
        "problem": "Shortest paths in a DAG",
        "recommended_method": "Topological-order dynamic programming",
        "reason": "Each vertex is processed after all possible predecessors."
      },
      {
        "problem": "Minimum total cost of connecting all vertices",
        "recommended_method": "Kruskal or Prim",
        "reason": "The objective is a minimum spanning tree."
      },
      {
        "problem": "Maximum transferable resource with edge capacities",
        "recommended_method": "Maximum flow, preferably Dinic for a reusable implementation",
        "reason": "The network exactly represents capacity and conservation constraints."
      },
      {
        "problem": "Maximum cardinality matching in a bipartite graph",
        "recommended_method": "Hopcroft-Karp or a unit-capacity flow network",
        "reason": "Unit capacities encode one-to-one matching."
      }
    ],
